<script>
import axios from 'axios'

export default {
  name: 'linkGet',
  methods: {
    async getLinkList(inputText) {
      try {
        const net = '' 
        const net_files = `${net}/files`
        const jsonFile = `${net_files}/infos/infos.json`

        const response = await axios.get(jsonFile)
        const infosData = response.data

        const text = inputText?.trim() || ''

        if (!text) return []
        
        const difColor_map = {
          'EZ': '#0D9A28',
          'HD': '#0175B8',
          'IN': '#CF1313',
          'AT': '#383838',
          'LY': '#383838',
          'SP': '#383838'
        }

        const chartStrings = text.split(/\s+/)
        const result = []

        for (const str of chartStrings) {
          if (!str) continue
          
          const difficulty = str.slice(-2)
          const chartId = str.slice(0, -2)

          const chartInfo = infosData[chartId]
          if (!chartInfo) continue

          result.push({
            id: chartId,
            name: chartInfo.name || 'UNKNOWN',
            dif: chartInfo[difficulty]?.dif || '?',
            color: difColor_map[difficulty] || '#383838',
            difficulty: difficulty,
            imgPath: `${net}/assets/illLow/${chartId}.png`,
            score: 0
          })
        }
        console.log(result)
        return result
        
      } catch (error) {
        console.error('获取链接列表失败：', error)
        return []
      }
    }
  }
}
</script>